PART_SEQUENCES = {
    "BBa_E0040": "",
    "BBa_E0010": "",
    "BBa_R0040": "TCCATATAATGCCTAGCTTACCCCTTACCCCTCCCAGACAGATCTCATGAATCAAACTAGCTTGTTGAATACAAATCCGATCCCTATAAT",
    "BBa_B0034": "AAAGAGGAGAAA",
    "BBa_B0015": "CGGCCGCTTCAAATAACGCGGCTGCTTTCGCCGCTGCTGAACGCCGGATCTGTTTTTTTCACGTCTGCACTGAGATTTGGCACTGCCGTCGTTTTACAACGTCGTGACTGGGAAAACCCTGGCGTTACCCAACTTAATCGCCTTGCAGCACATCCCCCTTTCGCCAGCTGGCGTAATAGCGAAGAGGCCCGCACCGATCGCCCTTCCCAACAGTTGCGCAGCCTGAATGGCGAACGGCCT",
    "BBa_K145001": "",
    "BBa_I13458": "",
    "BBa_C0040": "",
    "BBa_C0012": "",
    "BBa_C0051": "",
    "BBa_K1847000": "TCCATATAATGCCTAGCTTACCCCTTACCCCTCCCAGACAGATCTCATGAATCAAACTAGCTTGTTGAATACAAATCCGATCCCTATAATCGAGTCTAGACTGCAGGTCAACATCCTTTGTACAAAATGGAGGAACTAAGAGGATCCAGATCTAGCTTACCCCTTACCCCTCCCAGACAGATCTCATGAATCAAACTAGCTTGTTGAATACAAATCCGATCCCTATAAT",
    "BBa_K1847001": "TCCATATAATGCCTAGCTTACCCCTTACCCCTCCCAGACAGATCTCATGAATCAAACTAGCTTGTTGAATACAAATCCGATCCCTATAATCGAGTCTAGACTGCAGGTCAACATCCTTTGTACAAAATGGAGGAACTAAGAGGATCCAGATCTAGCTTACCCCTTACCCCTCCCAGACAGATCTCATGAATCAAACTAGCTTGTTGAATACAAATCCGATCCCTATAAT",
}

FALLBACK_SEQUENCE = "NNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNNN"


class DNABackend(Backend):
    @property
    def name(self):
        return "DNA"

    def generate(self, cir, circuit_name="circuit"):
        parts = cir.parts_deduplicated()
        lines = [f">{circuit_name} complete construct"]
        construct = ""
        for part in parts:
            pid = part.get("id", "unknown")
            seq = PART_SEQUENCES.get(pid, FALLBACK_SEQUENCE)
            construct += seq
        lines.append(construct)
        for i, part in enumerate(parts):
            pid = part.get("id", "unknown")
            info = part.get("info", "")
            seq = PART_SEQUENCES.get(pid, FALLBACK_SEQUENCE)
            lines.append(f">{pid} | {info}")
            lines.append(seq)
        return "\n".join(lines)

    def generate_fasta(self, cir, circuit_name="circuit"):
        return self.generate(cir, circuit_name)
